import { config } from "dotenv";
import Fastify from "fastify";
import cors from "@fastify/cors";
import cookie from "@fastify/cookie";
import session from "@fastify/session";
import RedisStore from "connect-redis";
import { createClient } from "redis";
import { authRoutes } from "@/features/auth/routes";

config();

async function main(): Promise<void> {
  const app = Fastify({ logger: true });

  const redisClient = createClient();
  await redisClient.connect();

  await app.register(cors, {
    origin: String(process.env.CORS_ORIGIN ?? "http://localhost:3000").split(","),
    credentials: true,
  });

  await app.register(cookie);
  await app.register(session, {
    secret: String(process.env.SESSION_SECRET),
    store: new RedisStore({ client: redisClient, prefix: "auth:" }),
    cookieName: process.env.SESSION_COOKIE_NAME ?? "sid",
    cookie: { secure: process.env.NODE_ENV === "production", httpOnly: true },
  });

  await app.register(authRoutes, { prefix: "/auth" });

  const port = Number(process.env.PORT ?? 4000);
  await app.listen({ port });
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import type { FastifyInstance } from "fastify";
import { validate } from "@/features/auth/middlewares/validate";
import { signupSchema } from "@/features/auth/validation/signup";
import { loginSchema } from "@/features/auth/validation/login";
import { signupHandler } from "@/features/auth/controllers/signupHandler";
import { loginHandler } from "@/features/auth/controllers/loginHandler";
import { logoutHandler } from "@/features/auth/controllers/logoutHandler";
import { meHandler } from "@/features/auth/controllers/meHandler";

export async function authRoutes(app: FastifyInstance): Promise<void> {
  app.post("/signup", { preHandler: validate(signupSchema) }, signupHandler);
  app.post("/login", { preHandler: validate(loginSchema) }, loginHandler);
  app.get("/logout", logoutHandler);
  app.get("/me", meHandler);
}

import type { FastifyRequest, FastifyReply } from "fastify";
import type { ZodSchema } from "zod";

export const validate =
  (schema: ZodSchema) =>
  async (req: FastifyRequest, reply: FastifyReply) => {
    const result = schema.safeParse(req.body);

    if (!result.success) {
      return reply.status(400).send({
        message: "Validation failed",
        errors: result.error.flatten().fieldErrors,
      });
    }

    req.body = result.data;
  };

import type { FastifyRequest, FastifyReply } from "fastify";
import argon2 from "argon2";
import { prisma } from "@/config";

export const signupHandler = async (req: FastifyRequest, reply: FastifyReply) => {
  const details = req.body as { name: string; email: string; password: string };

  const hashedPassword = await argon2.hash(details.password);

  const user = await prisma.user.create({
    data: { name: details.name, email: details.email, password: hashedPassword },
    select: { id: true, email: true, name: true },
  });

  req.session.userId = String(user.id);

  return reply.status(200).send(user);
};

import type { FastifyRequest, FastifyReply } from "fastify";
import argon2 from "argon2";
import { prisma } from "@/config";

export const loginHandler = async (req: FastifyRequest, reply: FastifyReply) => {
  const credentials = req.body as { email: string; password: string };

  const user = await prisma.user.findUnique({
    where: { email: credentials.email },
    select: { id: true, name: true, email: true, password: true },
  });

  if (!user) {
    return reply.status(404).send({ message: "User not found" });
  }

  const valid = await argon2.verify(user.password, credentials.password);
  if (!valid) {
    return reply.status(401).send({ message: "Invalid credentials" });
  }

  req.session.userId = String(user.id);

  return reply.status(200).send({ id: user.id, name: user.name, email: user.email });
};

import type { FastifyRequest, FastifyReply } from "fastify";

export const logoutHandler = async (req: FastifyRequest, reply: FastifyReply) => {
  await req.session.destroy();
  return reply.status(200).send({ message: "User logged out successfully" });
};

import type { FastifyRequest, FastifyReply } from "fastify";
import { prisma } from "@/config";

export const meHandler = async (req: FastifyRequest, reply: FastifyReply) => {
  const userId = req.session.userId;

  if (!userId) {
    return reply.status(401).send({ message: "Not authenticated" });
  }

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { id: true, email: true, name: true },
  });

  return reply.status(200).send(user);
};

import { z } from "zod";

export const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
});

export type LoginInput = z.infer<typeof loginSchema>;

import { z } from "zod";

export const signupSchema = z.object({
  name: z.string().min(1),
  email: z.string().email(),
  password: z.string().min(8),
});

export type SignupInput = z.infer<typeof signupSchema>;

import "@fastify/session";

declare module "fastify" {
  interface Session {
    userId?: string;
  }
}
